target as (
 select l.id as lesson_id,p.item
 from public.countries c
 join public.curricula cur on cur.country_id=c.id
 join public.grades g on g.curriculum_id=cur.id
 join public.units u on u.grade_id=g.id
 join public.lessons l on l.unit_id=u.id
 join payload p on (p.item->>'order')::integer=l.lesson_number
    and p.item->>'lessonTitle'=l.title
 where c.code='BH' and cur.academic_year='2026-2027'
  and cur.name_ar='اللغة العربية — التعليم المستمر'
  and g.name_ar='الأول محو الأمية' and g.grade_number is null
  and u.semester=1 and l.semester=1
  and l.instructions @> '[{"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT"}]'::jsonb
)
insert into public.lesson_activities(
 lesson_id,title,activity_type,instructions,content,
 activity_order,points,is_published,section,prompt,answer,is_required
)
select t.lesson_id,
 'تحقّق من فهمك — تدريب أصلي من ضاديوم',
 'multiple_choice',
 'اقرأ السؤال ثم اختر إجابة واحدة. هذا نشاط داعم من تأليف ضاديوم، وليس سؤالًا مقتبسًا من الكتاب الرسمي.',
 jsonb_build_object('origin','DADYOOM_BH_CONTINUING_LITERACY1_MCQ_V1','options',t.item->'options','editorial_review','required','book_text_copied',false),
 1,5,true,'assessment',t.item->>'prompt',
 jsonb_build_object('correct',t.item->>'correct'),false
from target t
where not exists (
 select 1 from public.lesson_activities a
 where a.lesson_id=t.lesson_id
  and a.content->>'origin'='DADYOOM_BH_CONTINUING_LITERACY1_MCQ_V1'
);
